WITH remaining_keys AS (SELECT customer_id, id FROM orders EXCEPT ALL SELECT customer_id, id FROM orders WHERE amount BETWEEN 1040 AND 1150), verified AS (SELECT s.* FROM orders s INNER JOIN remaining_keys k ON s.customer_id = k.customer_id AND s.id = k.id) SELECT s.customer_id, s.store_id, s.status, s.channel, CASE WHEN status RLIKE '^(CANCELLED|SHIPPED)$' THEN 'GROUP_B' WHEN status RLIKE '^(COMPLETED|PENDING)$' THEN 'OTHER_ZONE' ELSE 'EXTENDED' END AS status_zone, (SELECT MIN(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS min_subscription_monthly_fee FROM verified s ORDER BY min_subscription_monthly_fee DESC, customer_id ASC;
